def _reject_http_span_kind(kind: Any, attributes: Dict[str, Any]) -> None:
    candidates = (
        kind,
        attributes.get("neatlogs.span.kind"),
        attributes.get("openinference.span.kind"),
    )
    if any(str(value or "").strip().upper() == "HTTP" for value in candidates):
        raise NeatlogsConfigurationError(
            "HTTP spans are not supported. Trace the semantic LLM, TOOL, "
            "RETRIEVER, or other AI operation instead."
        )

def _trace_sampler(sample_rate: float) -> ParentBased:
    """Validate one trace-level rate and preserve the parent's sampling decision."""
    if isinstance(sample_rate, bool) or not isinstance(sample_rate, (int, float)):
        raise NeatlogsConfigurationError("sample_rate must be a finite number from 0.0 to 1.0")
    rate = float(sample_rate)
    if not math.isfinite(rate) or rate < 0.0 or rate > 1.0:
        raise NeatlogsConfigurationError("sample_rate must be a finite number from 0.0 to 1.0")
    return ParentBased(root=TraceIdRatioBased(rate))

def _safe_use_span(
    span: Span,
    end_on_exit: bool = False,
    record_exception: bool = True,
    set_status_on_exception: bool = True,
) -> Iterator[Span]:
    if not _is_isolated_span(span):
        with _ORIGINAL_USE_SPAN(
            span,
            end_on_exit=end_on_exit,
            record_exception=record_exception,
            set_status_on_exception=set_status_on_exception,
        ) as current_span:
            yield current_span
        return

    token = context_api.attach(set_neatlogs_span_in_context(span, force_owned=True))
    try:
        try:
            yield span
        finally:
            context_api.detach(token)
    except Exception as exc:
        if isinstance(span, Span) and span.is_recording():
            if record_exception:
                span.record_exception(exc)
            if set_status_on_exception:
                span.set_status(
                    Status(
                        status_code=StatusCode.ERROR,
                        description=f"{type(exc).__name__}: {exc}",
                    )
                )
        raise
    finally:
        if end_on_exit:
            span.end()

def _is_isolated_span(span: Any) -> bool:
    if bool(getattr(span, _ISOLATED_MARKER, False)):
        return True
    return bool(getattr(getattr(span, "__wrapped__", None), _ISOLATED_MARKER, False))
